insert into public.stories(id,owner_id,title,organization,role,situation,task,actions,result,source,created_at) select id,owner_id,title,organization,role,situation,task,actions,result,source,created_at from jsonb_populate_recordset(null::public.stories,'[{"id": "0623c4d5-8689-5391-8818-6078f94b8142", "owner_id": "eba2d5fb-c704-44fc-924b-b180e6720be4", "title": "[Demo] Campus Food Rescue", "organization": "Campus Service Lab", "role": "Volunteer coordinator", "situation": "During a campus food drive, three volunteer teams collected donations but nobody owned delivery scheduling. Two shelters received duplicate deliveries while another waited.", "task": "I was responsible for aligning twelve volunteers and creating a reliable delivery plan before the next weekend.", "actions": "I interviewed each team lead, mapped delivery windows, and assigned one owner to every route. I chose a shared checklist because everyone could use it without training. I tested the handoff with two drivers and adjusted the pickup order.", "result": "As a result, we delivered 180 meals across three shelters without a missed pickup. The checklist prevented duplicate routes. I learned to verify ownership before adding more volunteers.", "source": "manual", "created_at": "2026-09-01T14:00:00Z"}, {"id": "0146efb5-616f-5f3a-bc45-4e19b00c5356", "owner_id": "eba2d5fb-c704-44fc-924b-b180e6720be4", "title": "[Demo] Mentoring the Robotics Team", "organization": "Student Robotics Club", "role": "Software mentor", "situation": "During our robot build, new members waited for a senior developer whenever a sensor test failed. The backlog delayed integration.", "task": "My task was to help four beginners debug independently while keeping the robot ready for a demonstration.", "actions": "I created a troubleshooting guide, paired each beginner with a teammate, and led short debugging sessions. I compared lecture-style training with hands-on exercises and chose exercises because members could practice the failure themselves.", "result": "As a result, the team resolved eight sensor failures independently and completed integration two days early. I learned to measure mentoring by the decisions others can make without me.", "source": "manual", "created_at": "2026-09-02T14:00:00Z"}, {"id": "1d7b770f-731f-555f-bc7f-c87654825f37", "owner_id": "eba2d5fb-c704-44fc-924b-b180e6720be4", "title": "[Demo] Resolving a Dashboard Disagreement", "organization": "Civic Data Studio", "role": "Frontend collaborator", "situation": "During a dashboard project, designers wanted richer charts while backend teammates wanted to reduce API complexity. Meetings became repetitive and the deadline approached.", "task": "I was responsible for finding an approach that both teams could support without sacrificing accessibility.", "actions": "I asked each teammate to explain their constraints and summarized the shared goal. I built two prototypes and compared loading time and keyboard navigation. I chose a simpler chart with optional details because it preserved the key information.", "result": "As a result, both teams adopted the prototype and delivered the dashboard on time. Testing with six volunteers found no blocked keyboard tasks. I learned to turn disagreement into a testable decision.", "source": "manual", "created_at": "2026-09-03T14:00:00Z"}, {"id": "4ca2cd70-0131-5199-a1ab-04a3be8f3d32", "owner_id": "eba2d5fb-c704-44fc-924b-b180e6720be4", "title": "[Demo] Coordinating a Research Handoff", "organization": "Community Research Lab", "role": "Research assistant", "situation": "During a research project, two students used different definitions for survey categories. Their results disagreed even though they used the same dataset.", "task": "My task was to coordinate a reproducible analysis and protect the original responses.", "actions": "I scheduled a joint review, documented disputed definitions, and created a shared coding guide. I tested the guide on twenty responses with both students and compared disagreements before processing the full dataset.", "result": "As a result, agreement rose from 72 percent to 94 percent and the team delivered a reproducible report. I learned to make assumptions explicit before dividing analysis work.", "source": "manual", "created_at": "2026-09-04T14:00:00Z"}, {"id": "dfeafaf1-a77e-5b4c-9698-a6d4ab40b426", "owner_id": "eba2d5fb-c704-44fc-924b-b180e6720be4", "title": "[Demo] Fixing a Slow Search Endpoint", "organization": "Harbor Software Demo", "role": "Backend intern", "situation": "During a product trial, users reported that search sometimes took several seconds. The team initially suspected network latency.", "task": "I was responsible for finding the bottleneck without disrupting the trial or exposing customer data.", "actions": "I added request timing, reproduced the issue with synthetic data, and compared query plans. I found a missing index and tested it against a caching approach. I chose the index because it removed the bottleneck without stale results.", "result": "As a result, median search latency fell from 1400 to 190 milliseconds in the test workload. The improvement enabled the trial to continue. I learned to measure each layer before choosing a fix.", "source": "manual", "created_at": "2026-09-05T14:00:00Z"}, {"id": "224c867e-988c-57b0-a156-f86c05ab0a0e", "owner_id": "eba2d5fb-c704-44fc-924b-b180e6720be4", "title": "[Demo] Building an Accessible Route Planner", "organization": "Open Campus Maps", "role": "Student developer", "situation": "During a campus mapping project, the shortest route sometimes included stairs that wheelchair users could not use.", "task": "My task was to build a route filter that respected accessibility constraints and explained missing route data.", "actions": "I modeled step-free edges, wrote graph tests, and compared route outputs with manual checks. I interviewed two accessibility volunteers and tested detours. I chose explicit unknown labels instead of assuming every unmarked entrance was accessible.", "result": "As a result, all twelve reviewed routes avoided known stairs and displayed uncertain entrances. The design prevented misleading directions. I learned that missing data must be visible to users.", "source": "manual", "created_at": "2026-09-06T14:00:00Z"}, {"id": "915a89b7-248b-5903-8cfe-58d768553cf8", "owner_id": "eba2d5fb-c704-44fc-924b-b180e6720be4", "title": "[Demo] Recovering from a Failed Release", "organization": "Harbor Software Demo", "role": "Release owner", "situation": "During a student app release, I changed a response format without checking an older client. The release broke sign-in for the test group.", "task": "I was responsible for restoring service, explaining my mistake, and preventing a repeat.", "actions": "I rolled back the release, notified the team, and reproduced the failure. I added compatibility tests and compared a staged rollout with a full launch. I chose a staged rollout because it limited the impact of future mistakes.", "result": "As a result, access was restored in eighteen minutes and the next release passed compatibility checks. I learned to test assumptions at system boundaries and own the communication as well as the fix.", "source": "manual", "created_at": "2026-09-07T14:00:00Z"}, {"id": "d4d16968-1542-5ffb-81f0-4bc1480271ad", "owner_id": "eba2d5fb-c704-44fc-924b-b180e6720be4", "title": "[Demo] Rescoping an Overambitious Prototype", "organization": "Student Design Sprint", "role": "Project teammate", "situation": "During a weekend build, I committed to three integrations before testing their authentication flows. We lost the first afternoon to setup.", "task": "My task was to recover a working demonstration and acknowledge that my estimate had been unrealistic.", "actions": "I listed the remaining risks, asked teammates which workflow mattered most, and cut two integrations. I built a local data adapter and tested the complete user journey rather than polishing isolated screens.", "result": "As a result, we demonstrated one complete workflow instead of three broken ones. I learned to validate the riskiest dependency before committing the team to a schedule.", "source": "manual", "created_at": "2026-09-08T14:00:00Z"}, {"id": "ecadb487-9875-5e73-83d4-18984ca71864", "owner_id": "eba2d5fb-c704-44fc-924b-b180e6720be4", "title": "[Demo] Prioritizing an Unclear Support Tool", "organization": "Civic Data Studio", "role": "Product engineering intern", "situation": "During a support-tool project, stakeholders asked for automation but disagreed about which tasks should be automated. There was no agreed success metric.", "task": "I was responsible for proposing a small, reversible first release using limited evidence.", "actions": "I reviewed anonymized task logs, interviewed three support agents, and ranked tasks by frequency and error cost. I compared full automation with a suggested-response workflow and chose suggestions because agents could review uncertain cases.", "result": "As a result, the pilot reduced median handling time by 22 percent while keeping human approval. I learned to define a decision rule before debating features.", "source": "manual", "created_at": "2026-09-09T14:00:00Z"}, {"id": "1e688771-4ed7-553a-b77b-0c1d80c6fd4e", "owner_id": "eba2d5fb-c704-44fc-924b-b180e6720be4", "title": "[Demo] Adapting a Workshop to Limited Resources", "organization": "Campus Service Lab", "role": "Workshop organizer", "situation": "During a coding workshop, half the attendees arrived without laptops and the venue internet failed. The original lesson assumed both were available.", "task": "My task was to preserve a useful learning experience while changing the plan in ten minutes.", "actions": "I paired attendees, moved the first exercise to paper, and split the lesson into offline activities. I asked volunteers to check understanding after each step and chose one small working example instead of covering every planned topic.", "result": "As a result, twenty attendees completed the core exercise and twelve requested the follow-up materials. I learned to define the learning outcome separately from the tools used to teach it.", "source": "manual", "created_at": "2026-09-10T14:00:00Z"}, {"id": "209fca54-d22b-541c-b38c-25fda6a0ff95", "owner_id": "eba2d5fb-c704-44fc-924b-b180e6720be4", "title": "[Demo draft] Planning a sustainability event", "organization": "Campus Service Lab", "role": "Volunteer coordinator", "situation": "During a campus food drive, three volunteer teams collected donations but nobody owned delivery scheduling. Two shelters received duplicate deliveries while another waited.", "task": "I was responsible for aligning twelve volunteers and creating a reliable delivery plan before the next weekend.", "actions": "", "result": "", "source": "manual", "created_at": "2026-09-01T14:00:00Z"}, {"id": "85e1bcdb-2a5f-502a-97a9-423db8ae5be5", "owner_id": "eba2d5fb-c704-44fc-924b-b180e6720be4", "title": "[Demo draft] Organizing a peer study group", "organization": "Student Robotics Club", "role": "Software mentor", "situation": "During our robot build, new members waited for a senior developer whenever a sensor test failed. The backlog delayed integration.", "task": "My task was to help four beginners debug independently while keeping the robot ready for a demonstration.", "actions": "", "result": "", "source": "manual", "created_at": "2026-09-02T14:00:00Z"}]'::jsonb) on conflict(id) do nothing;
