hip": {"individual": 3, "team": 0}, "activity": null, "redundancy_ratio": 0.0}, "analysis": {"scores": {"Delivery": 49.4, "Structure": 53.5, "Specificity": 49.5, "Impact": 0.0, "Overall": 38.1}, "score_explanation": "Overall averages the available category scores. Delivery weights pace around 145 WPM (70%) and long-gap control (30%). Structure combines meaningful STAR coverage (50%), a 15/10/50/25 time balance (35%), and section order (15%), scaled by coverage. Specificity rewards personal actions (25%), reasoning (25%), verification (20%), concrete detail (20%), and precise wording (10%), scaled by action depth and repetition. Relevance uses word-weighted semantic similarity, mapped from 0.05\u20130.75 to 0\u2013100; it is omitted when unavailable. Impact rewards an observable outcome (35%), a measure (25%), learning (20%), and a causal link (20%), scaled by result detail. Targets are adjustable coaching heuristics, not validated hiring standards.", "summary": "End with what changed, a truthful measure if available, or a concrete lesson.", "strengths": [{"kind": "observation", "text": "You included concrete numeric details. Preserve these when tightening the answer; a number is not by itself proof of impact.", "segments": [0, 2]}, {"kind": "observation", "text": "You supplied 67 words of material to refine. Use the highlighted passage as a starting point, not a completed answer.", "segments": [0]}], "improvements": [{"kind": "recommendation", "text": "End with what changed, a truthful measure if available, or a concrete lesson.", "segments": [3]}, {"kind": "recommendation", "text": "Rehearse the highlighted action in two sentences: what you chose, then why that choice mattered.", "segments": [2]}, {"kind": "recommendation", "text": "Tie the final sentence directly to the question; explain what this example demonstrates.", "segments": [3]}], "exercise": "Record another answer using four short beats: context, your responsibility, your decision and reason, then the observable outcome. End with what changed, a truthful measure if available, or a concrete lesson.", "outline": [{"section": "situation", "segments": [0], "prompt": "One sentence: what problem mattered?"}, {"section": "task", "segments": [1], "prompt": "One sentence: what did you own?"}, {"section": "actions", "segments": [2, 3], "prompt": "Two sentences: what did you decide, do, and verify?"}, {"section": "result", "segments": [], "prompt": "One sentence: what changed or what did you learn?"}], "intersections": [{"kind": "inference", "text": "Detected context takes 61% of transcript-segment time; actions take 39%. Review the section labels before using this balance.", "segments": [0, 1, 2, 3]}, {"kind": "inference", "text": "Detected actions pace is 200 WPM versus 116 WPM for the full recording. Segment pace excludes between-segment pauses.", "segments": [2, 3]}], "confidence": "limited", "limitations": ["Fictional demo dataset: transcript and timestamps are generated examples, not a recorded interview.", "Transcription can miss words or mishear numbers; check the transcript.", "STAR and relevance use an uncalibrated local similarity model, not a trained interview evaluator.", "Numeric mentions are evidence cues, not fact checking. Vague-word flags do not prove a claim is unsupported.", "No assessment of personality, honesty, emotion, confidence, accent, or employability.", "Sentence boundaries depend on transcription punctuation. Segment time is not the same as pure speech time."], "semantic_method": "rules-only (semantic model unavailable)", "intent_assessment": "Semantic overlap is a preliminary relevance signal; it cannot establish that the interviewer\u2019s intent was fully answered.", "ownership_clarity": "3 individual versus 0 team pronouns. Team language is appropriate; clarify your own decision when relevant.", "action_depth": "0 segments contain decision or verification cues. Inspect the linked transcript, not just the count.", "result_strength": "0 Result segments; 0 include a numeric mention.", "coherence": "0 backward transitions in inferred STAR order. This is a review cue, not a logical-coherence verdict."}, "pipeline_version": "demo-seed-september-2026", "rubric_version": "coaching-3.0", "is_mock": false, "error": null, "owner_id": "eba2d5fb-c704-44fc-924b-b180e6720be4"}'::jsonb) on conflict(id) do nothing;
