insert into public.practice_segments values ('237c8c06-43e3-5da4-adda-14ee5472cb52',1,'{"index": 1, "start": 9.942, "end": 16.686, "text": "My task was to help four beginners debug independently while keeping the robot ready for a demonstration.", "words": [{"text": "My", "start": 9.942, "end": 10.286, "confidence": 0.95}, {"text": "task", "start": 10.342, "end": 10.686, "confidence": 0.95}, {"text": "was", "start": 10.742, "end": 11.086, "confidence": 0.95}, {"text": "to", "start": 11.142, "end": 11.486, "confidence": 0.95}, {"text": "help", "start": 11.542, "end": 11.886, "confidence": 0.95}, {"text": "four", "start": 11.942, "end": 12.286, "confidence": 0.95}, {"text": "beginners", "start": 12.342, "end": 12.686, "confidence": 0.95}, {"text": "debug", "start": 12.742, "end": 13.086, "confidence": 0.95}, {"text": "independently", "start": 13.142, "end": 13.486, "confidence": 0.95}, {"text": "while", "start": 13.542, "end": 13.886, "confidence": 0.95}, {"text": "keeping", "start": 13.942, "end": 14.286, "confidence": 0.95}, {"text": "the", "start": 14.342, "end": 14.686, "confidence": 0.95}, {"text": "robot", "start": 14.742, "end": 15.086, "confidence": 0.95}, {"text": "ready", "start": 15.142, "end": 15.486, "confidence": 0.95}, {"text": "for", "start": 15.542, "end": 15.886, "confidence": 0.95}, {"text": "a", "start": 15.942, "end": 16.286, "confidence": 0.95}, {"text": "demonstration.", "start": 16.342, "end": 16.686, "confidence": 0.95}], "star": "actions", "relevance": null, "evidence": true, "vague": false, "wpm": 151.2}'::jsonb) on conflict do nothing;
insert into public.practice_segments values ('237c8c06-43e3-5da4-adda-14ee5472cb52',2,'{"index": 2, "start": 17.742, "end": 29.764, "text": "I created a troubleshooting guide, paired each beginner with a teammate, and led short debugging sessions. I compared lecture-style training with hands-on exercises and chose exercises because members could practice the failure themselves.", "words": [{"text": "I", "start": 17.742, "end": 18.057, "confidence": 0.95}, {"text": "created", "start": 18.108, "end": 18.422, "confidence": 0.95}, {"text": "a", "start": 18.474, "end": 18.788, "confidence": 0.95}, {"text": "troubleshooting", "start": 18.839, "end": 19.154, "confidence": 0.95}, {"text": "guide,", "start": 19.205, "end": 19.52, "confidence": 0.95}, {"text": "paired", "start": 19.571, "end": 19.886, "confidence": 0.95}, {"text": "each", "start": 19.937, "end": 20.252, "confidence": 0.95}, {"text": "beginner", "start": 20.303, "end": 20.618, "confidence": 0.95}, {"text": "with", "start": 20.669, "end": 20.983, "confidence": 0.95}, {"text": "a", "start": 21.035, "end": 21.349, "confidence": 0.95}, {"text": "teammate,", "start": 21.4, "end": 21.715, "confidence": 0.95}, {"text": "and", "start": 21.766, "end": 22.081, "confidence": 0.95}, {"text": "led", "start": 22.132, "end": 22.447, "confidence": 0.95}, {"text": "short", "start": 22.498, "end": 22.813, "confidence": 0.95}, {"text": "debugging", "start": 22.864, "end": 23.179, "confidence": 0.95}, {"text": "sessions.", "start": 23.23, "end": 23.544, "confidence": 0.95}, {"text": "I", "start": 23.596, "end": 23.91, "confidence": 0.95}, {"text": "compared", "start": 23.961, "end": 24.276, "confidence": 0.95}, {"text": "lecture-style", "start": 24.327, "end": 24.642, "confidence": 0.95}, {"text": "training", "start": 24.693, "end": 25.008, "confidence": 0.95}, {"text": "with", "start": 25.059, "end": 25.374, "confidence": 0.95}, {"text": "hands-on", "start": 25.425, "end": 25.739, "confidence": 0.95}, {"text": "exercises", "star