insert into public.practice_segments values ('1c0793e9-256a-5867-93aa-9f61b140d990',1,'{"index": 1, "start": 9.168, "end": 15.112, "text": "I was responsible for finding the bottleneck without disrupting the trial or exposing customer data.", "words": [{"text": "I", "start": 9.168, "end": 9.512, "confidence": 0.95}, {"text": "was", "start": 9.568, "end": 9.912, "confidence": 0.95}, {"text": "responsible", "start": 9.968, "end": 10.312, "confidence": 0.95}, {"text": "for", "start": 10.368, "end": 10.712, "confidence": 0.95}, {"text": "finding", "start": 10.768, "end": 11.112, "confidence": 0.95}, {"text": "the", "start": 11.168, "end": 11.512, "confidence": 0.95}, {"text": "bottleneck", "start": 11.568, "end": 11.912, "confidence": 0.95}, {"text": "without", "start": 11.968, "end": 12.312, "confidence": 0.95}, {"text": "disrupting", "start": 12.368, "end": 12.712, "confidence": 0.95}, {"text": "the", "start": 12.768, "end": 13.112, "confidence": 0.95}, {"text": "trial", "start": 13.168, "end": 13.512, "confidence": 0.95}, {"text": "or", "start": 13.568, "end": 13.912, "confidence": 0.95}, {"text": "exposing", "start": 13.968, "end": 14.312, "confidence": 0.95}, {"text": "customer", "start": 14.368, "end": 14.712, "confidence": 0.95}, {"text": "data.", "start": 14.768, "end": 15.112, "confidence": 0.95}], "star": "task", "relevance": null, "evidence": false, "vague": false, "wpm": 151.4}'::jsonb) on conflict do nothing;
