insert into public.practice_attempts select * from jsonb_populate_record(null::public.practice_attempts,'{"id": "3dc0f6dc-997b-5795-9f21-8ea1781e68b1", "question_id": "prob-2", "prompt": "Tell me about a time you had to simplify an overly complicated system or process.", "competency": "problem_solving", "linked_story_id": "224c867e-988c-57b0-a156-f86c05ab0a0e", "created_at": "2026-09-18T16:00:00Z", "status": "completed", "duration": 37.39, "transcript": "During a campus mapping project, the shortest route sometimes included stairs that wheelchair users could not use. My task was to build a route filter that respected accessibility constraints and explained missing route data. I modeled step-free edges, wrote graph tests, and compared route outputs with manual checks. I interviewed two accessibility volunteers and tested detours. I chose explicit unknown labels instead of assuming every unmarked entrance was accessible. As a result, all twelve reviewed routes avoided known stairs and displayed uncertain entrances.", "metrics": {"duration": 37.39, "total_words": 83, "wpm": 133.2, "speaking_wpm": 179.9, "pace_definition": "WPM uses total recording time. Speaking WPM uses the sum of recognized word durations, not a physiological articulation measure.", "pauses": [], "pause_definition": "Gaps of at least 1.5s between recognized words; long gaps are at least 3s. These may include noise or unrecognized speech.", "repeated_phrases": [], "repeated_words": {}, "average_sentence_length": 13.8, "longest_monologue": 37.39, "star": {"situation": {"words": 17, "seconds": 6.53, "percent": 20.4}, "task": {"words": 0, "seconds": 0.0, "percent": 0.0}, "actions": {"words": 66, "seconds": 25.44, "percent": 79.6}, "result": {"words": 0, "seconds": 0.0, "percent": 0.0}, "unknown": {"words": 0, "seconds": 0.0, "percent": 0.0}}, "numeric_mentions": 1, "ownership": {"individual": 4, "team": 0}, "activity": null, "redundancy_ratio": 0.0}, "analysis": {"scores": {"Delivery": 91.7, "Structure":