insert into public.practice_attempts select * from jsonb_populate_record(null::public.practice_attempts,'{"id": "78192858-fb29-5744-bce4-5c9b6b8f8ad1", "question_id": "fail-1", "prompt": "Tell me about a significant mistake you made at work or on a project. How did you handle the fallout?", "competency": "failure", "linked_story_id": "915a89b7-248b-5903-8cfe-58d768553cf8", "created_at": "2026-09-19T13:00:00Z", "status": "completed", "duration": 40.06, "transcript": "During a student app release, I changed a response format without checking an older client. The release broke sign-in for the test group. I was responsible for restoring service, explaining my mistake, and preventing a repeat. I rolled back the release, notified the team, and reproduced the failure. I added compatibility tests and compared a staged rollout with a full launch. I chose a staged rollout because it limited the impact of future mistakes. As a result, access was restored in eighteen minutes and the next release passed compatibility checks.", "metrics": {"duration": 40.06, "total_words": 90, "wpm": 134.8, "speaking_wpm": 180.1, "pace_definition": "WPM uses total recording time. Speaking WPM uses the sum of recognized word durations, not a physiological articulation measure.", "pauses": [], "pause_definition": "Gaps of at least 1.5s between recognized words; long gaps are at least 3s. These may include noise or unrecognized speech.", "repeated_phrases": [{"phrase": "a staged rollout", "count": 2}], "repeated_words": {}, "average_sentence_length": 12.9, "longest_monologue": 40.06, "star": {"situation": {"words": 23, "seconds": 8.85, "percent": 25.5}, "task": {"words": 13, "seconds": 5.14, "percent": 14.8}, "actions": {"words": 54, "seconds": 20.65, "percent": 59.6}, "result": {"words": 0, "seconds": 0.0, "percent": 0.0}, "unknown": {"words": 0, "seconds": 0.0, "percent": 0.0}}, "numeric_mentions": 0, "ownership": {"individual": 6, "team": 0}, "activity": null, "redundancy_ratio": 0.011}, "analysi