insert into public.practice_segments values ('833bb2f3-7f53-5b0c-827d-efae4d9436a3',2,'{"index": 2, "start": 17.729, "end": 29.385, "text": "I listed the remaining risks, asked teammates which workflow mattered most, and cut two integrations. I built a local data adapter and tested the complete user journey rather than polishing isolated screens.", "words": [{"text": "I", "start": 17.729, "end": 18.044, "confidence": 0.95}, {"text": "listed", "start": 18.095, "end": 18.41, "confidence": 0.95}, {"text": "the", "start": 18.461, "end": 18.775, "confidence": 0.95}, {"text": "remaining", "start": 18.827, "end": 19.141, "confidence": 0.95}, {"text": "risks,", "start": 19.192, "end": 19.507, "confidence": 0.95}, {"text": "asked", "start": 19.558, "end": 19.873, "confidence": 0.95}, {"text": "teammates", "start": 19.924, "end": 20.239, "confidence": 0.95}, {"text": "which", "start": 20.29, "end": 20.605, "confidence": 0.95}, {"text": "workflow", "start": 20.656, "end": 20.97, "confidence": 0.95}, {"text": "mattered", "start": 21.022, "end": 21.336, "confidence": 0.95}, {"text": "most,", "start": 21.388, "end": 21.702, "confidence": 0.95}, {"text": "and", "start": 21.753, "end": 22.068, "confidence": 0.95}, {"text": "cut", "start": 22.119, "end": 22.434, "confidence": 0.95}, {"text": "two", "start": 22.485, "end": 22.8, "confidence": 0.95}, {"text": "integrations.", "start": 22.851, "end": 23.166, "confidence": 0.95}, {"text": "I", "start": 23.217, "end": 23.531, "confidence": 0.95}, {"text": "built", "start": 23.583, "end": 23.897, "confidence": 0.95}, {"text": "a", "start": 23.949, "end": 24.263, "confidence": 0.95}, {"text": "local", "start": 24.314, "end": 24.629, "confidence": 0.95}, {"text": "data", "start": 24.68, "end": 24.995, "confidence": 0.95}, {"text": "adapter", "start": 25.046, "end": 25.361, "confidence": 0.95}, {"text": "and", "start": 25.412, "end": 25.727, "confidence": 0.95}, {"text": "tested", "start": 25.778, "end": 26.092, "confidence": 0.95}, {"text": "the", "start": 26.144, "end": 26.458, "confidence": 0.95}, {"text": "complete", "start": 26.51, "end": 26.824, "confidence": 0.95}, {"text": "user", "start": 26.875, "end": 27.19, "confidence": 0.95}, {"text": "journey", "start": 27.241, "end": 27.556, "confidence": 0.95}, {"text": "rather", "start": 27.607, "end": 27.922, "confidence": 0.95}, {"text": "than", "start": 27.973, "end": 28.288, "confidence": 0.95}, {"text": "polishing", "start": 28.339, "end": 28.653, "confidence": 0.95}, {"text": "isolated", "start": 28.705, "end": 29.019, "confidence": 0.95}, {"text": "screens.", "start": 29.07, "end": 29.385, "confidence": 0.95}], "star": "actions", "relevance": null, "evidence": true, "vague": false, "wpm": 164.7}'::jsonb) on conflict do nothing;
