insert into public.practice_attempts select * from jsonb_populate_record(null::public.practice_attempts,'{"id": "e625dea2-e7ce-52c7-b078-6b2d70887d72", "question_id": "ambi-1", "prompt": "Tell me about a time you were assigned a project with ambiguous or poorly defined requirements.", "competency": "ambiguity", "linked_story_id": "ecadb487-9875-5e73-83d4-18984ca71864", "created_at": "2026-09-21T15:00:00Z", "status": "completed", "duration": 38.21, "transcript": "During a support-tool project, stakeholders asked for automation but disagreed about which tasks should be automated. There was no agreed success metric. I was responsible for proposing a small, reversible first release using limited evidence. I reviewed anonymized task logs, interviewed three support agents, and ranked tasks by frequency and error cost. I compared full automation with a suggested-response workflow and chose suggestions because agents could review uncertain cases. As a result, the pilot reduced median handling time by 22 percent while keeping human approval.", "metrics": {"duration": 38.21, "total_words": 85, "wpm": 133.5, "speaking_wpm": 179.6, "pace_definition": "WPM uses total recording time. Speaking WPM uses the sum of recognized word durations, not a physiological articulation measure.", "pauses": [], "pause_definition": "Gaps of at least 1.5s between recognized words; long gaps are at least 3s. These may include noise or unrecognized speech.", "repeated_phrases": [], "repeated_words": {}, "average_sentence_length": 14.2, "longest_monologue": 38.21, "star": {"situation": {"words": 22, "seconds": 8.46, "percent": 25.8}, "task": {"words": 13, "seconds": 5.14, "percent": 15.7}, "actions": {"words": 50, "seconds": 19.18, "percent": 58.5}, "result": {"words": 0, "seconds": 0.0, "percent": 0.0}, "unknown": {"words": 0, "seconds": 0.0, "percent": 0.0}}, "numeric_mentions": 2, "ownership": {"individual": 3, "team": 0}, "activity": null, "redundancy_ratio": 0.0}, "analysis": {"scores": {"Delive