insert into public.practice_attempts select * from jsonb_populate_record(null::public.practice_attempts,'{"id": "292b5d79-f033-52ea-951d-3d09165fbb9f", "question_id": "ambi-2", "prompt": "Describe a situation where you had to make a high-stakes decision without manager guidance.", "competency": "ambiguity", "linked_story_id": "1e688771-4ed7-553a-b77b-0c1d80c6fd4e", "created_at": "2026-09-22T16:00:00Z", "status": "completed", "duration": 40.08, "transcript": "During a coding workshop, half the attendees arrived without laptops and the venue internet failed. The original lesson assumed both were available. My task was to preserve a useful learning experience while changing the plan in ten minutes. I paired attendees, moved the first exercise to paper, and split the lesson into offline activities. I asked volunteers to check understanding after each step and chose one small working example instead of covering every planned topic. As a result, twenty attendees completed the core exercise and twelve requested the follow-up materials.", "metrics": {"duration": 40.08, "total_words": 90, "wpm": 134.7, "speaking_wpm": 180.0, "pace_definition": "WPM uses total recording time. Speaking WPM uses the sum of recognized word durations, not a physiological articulation measure.", "pauses": [], "pause_definition": "Gaps of at least 1.5s between recognized words; long gaps are at least 3s. These may include noise or unrecognized speech.", "repeated_phrases": [], "repeated_words": {}, "average_sentence_length": 15.0, "longest_monologue": 40.08, "star": {"situation": {"words": 22, "seconds": 8.46, "percent": 24.4}, "task": {"words": 0, "seconds": 0.0, "percent": 0.0}, "actions": {"words": 68, "seconds": 26.2, "percent": 75.6}, "result": {"words": 0, "seconds": 0.0, "percent": 0.0}, "unknown": {"words": 0, "seconds": 0.0, "percent": 0.0}}, "numeric_mentions": 2, "ownership": {"individual": 3, "team": 0}, "activity": null, "redundancy_ratio": 0.0}, "analysis": {"scores": {"Delivery": 92.