insert into public.practice_segments values ('ab5b2e6a-72b4-57bd-8dfb-deaeb7511509',1,'{"index": 1, "start": 12.057, "end": 18.892, "text": "I was responsible for aligning twelve volunteers and creating a reliable delivery plan before the next weekend.", "words": [{"text": "I", "start": 12.057, "end": 12.406, "confidence": 0.95}, {"text": "was", "start": 12.463, "end": 12.811, "confidence": 0.95}, {"text": "responsible", "start": 12.868, "end": 13.217, "confidence": 0.95}, {"text": "for", "start": 13.273, "end": 13.622, "confidence": 0.95}, {"text": "aligning", "start": 13.679, "end": 14.027, "confidence": 0.95}, {"text": "twelve", "start": 14.084, "end": 14.433, "confidence": 0.95}, {"text": "volunteers", "start": 14.49, "end": 14.838, "confidence": 0.95}, {"text": "and", "start": 14.895, "end": 15.244, "confidence": 0.95}, {"text": "creating", "start": 15.3, "end": 15.649, "confidence": 0.95}, {"text": "a", "start": 15.706, "end": 16.054, "confidence": 0.95}, {"text": "reliable", "start": 16.111, "end": 16.46, "confidence": 0.95}, {"text": "delivery", "start": 16.517, "end": 16.865, "confidence": 0.95}, {"text": "plan", "start": 16.922, "end": 17.271, "confidence": 0.95}, {"text": "before", "start": 17.327, "end": 17.676, "confidence": 0.95}, {"text": "the", "start": 17.733, "end": 18.081, "confidence": 0.95}, {"text": "next", "start": 18.138, "end": 18.487, "confidence": 0.95}, {"text": "weekend.", "start": 18.544, "end": 18.892, "confidence": 0.95}], "star": "task", "relevance": null, "evidence": false, "vague": false, "wpm": 149.2}'::jsonb) on conflict do nothing;
insert into public.practice_segments values ('ab5b2e6a-72b4-57bd-8dfb-deaeb7511509',2,'{"index": 2, "start": 19.949, "end": 34.992, "text": "I interviewed each team lead, mapped delivery windows, and assigned one owner to every route. I chose a shared checklist because everyone could use it without training. I tested the handoff with two drivers and adjusted the pickup order.", "words": [{"text": "I", "start": 19.949, "end": 20.282, "confidence": 0.95}, {"text": "interviewed", "start": 20.336, "end": 20.669, "confidence": 0.95}, {"text": "each", "start": 20.723, "end": 21.056, "confidence": 0.95}, {"text": "team", "start": 21.11, "end": 21.443, "confidence": 0.95}, {"text": "lead,", "start": 21.497, "end": 21.83, "confidence": 0.95}, {"text": "mapped", "start": 21.885, "end": 22.217, "confidence": 0.95}, {"text": "delivery", "start": 22.272, "end": 22.605, "confidence": 0.95}, {"text": "windows,", "start": 22.659, "end": 22.992, "confidence": 0.95}, {"text": "and", "start": 23.046, "end": 23.379, "confidence": 0.95}, {"text": "assigned", "start": 23.433, "end": 23.766, "confidence": 0.95}, {"text": "one", "start": 23.82, "end": 24.153, "confidence": 0.95}, {"text": "owner", "start": 24.207, "end": 24.54, "confidence": 0.95}, {"text": "to", "start": 24.594, "end": 24.927, "confidence": 0.95}, {"text": "every", "start": 24.981, "end": 25.314, "confidence": 0.95}, {"text": "route.", "start": 25.368, "end": 25.701, "confidence": 0.95}, {"text": "I", "start": 25.755, "end": 26.088, "confidence": 0.95}, {"text": "chose", "start": 26.143, "end": 26.475, "confidence": 0.95}, {"text": "a", "start": 26.53, "end": 26.863, "confidence": 0.95}, {"text": "shared", "start": 26.917, "end": 27.25, "confidence": 0.95}, {"text": "checklist", "start": 27.304, "end": 27.637, "confidence": 0.95}, {"text": "because", "start": 27.691, "end": 28.024, "confidence": 0.95}, {"text": "everyone", "start": 28.078, "end": 28.411, "confidence": 0.95}, {"text": "could", "start": 28.465, "end": 28.798, "confidence": 0.95}, {"text": "use", "start": 28.852, "end": 29.185, "confidence": 0.95}, {"text": "it", "start": 29.239, "end": 29.572, "confidence": 0.95}, {"text": "without", "start": 29.626, "end": 29.959, "confidence": 0.95}, {"text": "training.", "start": 30.014, "end": 30.346, "confidence": 0.95}, {"text": "I", "start": 30.401, "end": 30.734, "confidence": 0.95}, {"text": "tested", "start": 30.788, "end": 31.121, "confidence": 0.95}, {"text": "the", "start": 31.175, "end": 31.508, "confidence": 0.95}, {"text": "handoff", "start": 31.562, "end": 31.895, "confidence": 0.95}, {"text": "with", "start": 31.949, "end": 32.282, "confidence": 0.95}, {"text": "two", "start": 32.336, "end": 32.669, "confidence": 0.95}, {"text": "drivers", "start": 32.723, "end": 33.056, "confidence": 0.95}, {"text": "and", "start": 33.11, "end": 33.443, "confidence": 0.95}, {"text": "adjusted", "start": 33.497, "end": 33.83, "confidence": 0.95}, {"text": "the", "start": 33.885, "end": 34.217, "confidence": 0.95}, {"text": "pickup", "start": 34.272, "end": 34.605, "confidence": 0.95}, {"text": "order.", "start": 34.659, "end": 34.992, "confidence": 0.95}], "star": "actions", "relevance": null, "evidence": true, "vague": false, "wpm": 155.6}'::jsonb) on conflict do nothing;
insert into public.practice_segments values ('ab5b2e6a-72b4-57bd-8dfb-deaeb7511509',3,'{"index": 3, "start": 36.046, "end": 48.428, "text": "As a result, we delivered 180 meals across three shelters without a missed pickup. The checklist prevented duplicate routes. I learned to verify ownership before adding more volunteers.", "words": [{"text": "As", "start": 36.046, "end": 36.428, "confidence": 0.95}, {"text": "a", "start": 36.49, "end": 36.872, "confidence": 0.95}, {"text": "result,", "start": 36.935, "end": 37.317, "confidence": 0.95}, {"text": "we", "start": 37.379, "end": 37.761, "confidence": 0.95}, {"text": "delivered", "start": 37.824, "end": 38.206, "confidence": 0.95}, {"text": "180", "start": 38.268, "end": 38.65, "confidence": 0.95}, {"text": "meals", "start": 38.712, "end": 39.095, "confidence": 0.95}, {"text": "across", "start": 39.157, "end": 39.539, "confidence": 0.95}, {"text": "three", "start": 39.601, "end": 39.984, "confidence": 0.95}, {"text": "shelters", "start": 40.046, "end": 40.428, "confidence": 0.95}, {"text": "without", "start": 40.49, "end": 40.872, "confidence": 0.95}, {"text": "a", "start": 40.935, "end": 41.317, "confidence": 0.95}, {"text": "missed", "start": 41.379, "end": 41.761, "confidence": 0.95}, {"text": "pickup.", "start": 41.824, "end": 42.206, "confidence": 0.95}, {"text": "The", "start": 42.268, "end": 42.65, "confidence": 0.95}, {"text": "checklist", "start": 42.712, "end": 43.095, "confidence": 0.95}, {"text": "prevented", "start": 43.157, "end": 43.539, "confidence": 0.95}, {"text": "duplicate", "start": 43.601, "end": 43.984, "confidence": 0.95}, {"text": "routes.", "start": 44.046, "end": 44.428, "confidence": 0.95}, {"text": "I", "start": 44.49, "end": 44.872, "confidence": 0.95}, {"text": "learned", "start": 44.935, "end": 45.317, "confidence": 0.95}, {"text": "to", "start": 45.379, "end": 45.761, "confidence": 0.95}, {"text": "verify", "start": 45.824, "end": 46.206, "confidence": 0.95}, {"text": "ownership", "sta