insert into public.practice_attempts select * from jsonb_populate_record(null::public.practice_attempts,'{"id": "16d412db-57c5-5f94-bc53-ac1a10e76c15", "question_id": "lead-2", "prompt": "Describe a situation where you noticed an inefficiency and took the initiative to fix it.", "competency": "leadership", "linked_story_id": "0146efb5-616f-5f3a-bc45-4e19b00c5356", "created_at": "2026-09-24T14:00:00Z", "status": "completed", "duration": 46.33, "transcript": "During our robot build, new members waited for a senior developer whenever a sensor test failed. The backlog delayed integration. My task was to help four beginners debug independently while keeping the robot ready for a demonstration. I created a troubleshooting guide, paired each beginner with a teammate, and led short debugging sessions. I compared lecture-style training with hands-on exercises and chose exercises because members could practice the failure themselves. As a result, the team resolved eight sensor failures independently and completed integration two days early. I learned to measure mentoring by the decisions others can make without me.", "metrics": {"duration": 46.33, "total_words": 99, "wpm": 128.2, "speaking_wpm": 167.9, "pace_definition": "WPM uses total recording time. Speaking WPM uses the sum of recognized word durations, not a physiological articulation measure.", "pauses": [], "pause_definition": "Gaps of at least 1.5s between recognized words; long gaps are at least 3s. These may include noise or unrecognized speech.", "repeated_phrases": [], "repeated_words": {}, "average_sentence_length": 14.1, "longest_monologue": 46.33, "star": {"situation": {"words": 20, "seconds": 8.51, "percent": 20.8}, "task": {"words": 0, "seconds": 0.0, "percent": 0.0}, "actions": {"words": 79, "seconds": 32.38, "percent": 79.2}, "result": {"words": 0, "seconds": 0.0, "percent": 0.0}, "unknown": {"words": 0, "seconds": 0.0, "percent": 0.0}}, "numeric_mentions": 3, "ownership": {"individual": 5, "team": 1}, "activity": null, "redundancy_ratio": 0.0}, "analysis": {"scores": {"Delivery": 88.2, "Structure": 31.4, "Specificity": 100.0, "Impact": 0.0, "Overall": 54.9}, "score_explanation": "Overall averages the available category scores. Delivery weights pace around 145 WPM (70%) and long-gap control (30%). Structure combines meaningful STAR coverage (50%), a 15/10/50/25 time balance (35%), and section order (15%), scaled by coverage. Specificity rewards personal actions (25%), reasoning (25%), verification (20%), concrete detail (20%), and precise wording (10%), scaled by action depth and repetition. Relevance uses word-weighted semantic similarity, mapped from 0.05\u20130.75 to 0\u2013100; it is omitted when unavailable. Impact rewards an observable outcome (35%), a measure (25%), learning (20%), and a causal link (20%), scaled by result detail. Targets are adjustable coaching heuristics, not validated hiring standards.", "summary": "End with what changed, a truthful measure if available, or a concrete lesson.", "strengths": [{"kind": "observation", "text": "You included concrete numeric details. Preserve these when tightening the answer; a number is not by itself proof of impact.", "segments": [1, 3]}, {"kind": "observation", "text": "You described a decision or verification step. Keep the reasoning attached to your personal action.", "segments": [2]}], "improvements": [{"kind": "recommendation", "text": "End with what changed, a truthful measure if available, or a concrete lesson.", "segments": [3]}, {"kind": "recommendation", "text": "Name your personal responsibility and what success required.", "segments": [0]}, {"kind": "recommendation", "text": "Rehearse the highlighted action in two sentences: what you chose, then why that choice mattered.", "segments": [1]}], "exercise": "Record another answer using four short beats: context, your responsibility, your decision and reason, then the observable outcome. End with what changed, a truthful measure if available, or a concre