insert into public.practice_segments values ('16d412db-57c5-5f94-bc53-ac1a10e76c15',3,'{"index": 3, "start": 32.438, "end": 45.264, "text": "As a result, the team resolved eight sensor failures independently and completed integration two days early. I learned to measure mentoring by the decisions others can make without me.", "words": [{"text": "As", "start": 32.438, "end": 32.82, "confidence": 0.95}, {"text": "a", "start": 32.882, "end": 33.264, "confidence": 0.95}, {"text": "result,", "start": 33.326, "end": 33.709, "confidence": 0.95}, {"text": "the", "start": 33.771, "end": 34.153, "confidence": 0.95}, {"text": "team", "start": 34.215, "end": 34.598, "confidence": 0.95}, {"text": "resolved", "start": 34.66, "end": 35.042, "confidence": 0.95}, {"text": "eight", "start": 35.104, "end": 35.486, "confidence": 0.95}, {"text": "sensor", "start": 35.549, "end": 35.931, "confidence": 0.95}, {"text": "failures", "start": 35.993, "end": 36.375, "confidence": 0.95}, {"text": "independently", "start": 36.438, "end": 36.82, "confidence": 0.95}, {"text": "and", "start": 36.882, "end": 37.264, "confidence": 0.95}, {"text": "completed", "start": 37.326, "end": 37.709, "confidence": 0.95}, {"text": "integration", "start": 37.771, "end": 38.153, "confidence": 0.95}, {"text": "two", "start": 38.215, "end": 38.598, "confidence": 0.95}, {"text": "days", "start": 38.66, "end": 39.042, "confidence": 0.95}, {"text": "early.", "start": 39.104, "end": 39.486, "confidence": 0.95}, {"text": "I", "start": 39.549, "end": 39.931, "confidence": 0.95}, {"text": "learned", "start": 39.993, "end": 40.375, "confidence": 0.95}, {"text": "to", "start": 40.438, "end": 40.82, "confidence": 0.95}, {"text": "measure", "start": 40.882, "end": 41.264, "confidence": 0.95}, {"text": "mentoring", "start": 41.326, "end": 41.709, "confidence": 0.95}, {"text": "by", "start": 41.771, "end": 42.153, "confidence": 0.95}, {"text": "the", "start": 42.215, "end": 42.598, "confidence": 0.95}, {"text": "decisions", "st