insert into public.practice_attempts select * from jsonb_populate_record(null::public.practice_attempts,'{"id": "a7b405a4-0227-5a23-96dc-881400aac255", "question_id": "team-1", "prompt": "Tell me about a time you had a fundamental disagreement with a teammate and how you resolved it.", "competency": "teamwork", "linked_story_id": "1d7b770f-731f-555f-bc7f-c87654825f37", "created_at": "2026-09-24T15:00:00Z", "status": "completed", "duration": 50.07, "transcript": "During a dashboard project, designers wanted richer charts while backend teammates wanted to reduce API complexity. Meetings became repetitive and the deadline approached. I was responsible for finding an approach that both teams could support without sacrificing accessibility. I asked each teammate to explain their constraints and summarized the shared goal. I built two prototypes and compared loading time and keyboard navigation. I chose a simpler chart with optional details because it preserved the key information. As a result, both teams adopted the prototype and delivered the dashboard on time. Testing with six volunteers found no blocked keyboard tasks. I learned to turn disagreement into a testable decision.", "metrics": {"duration": 50.07, "total_words": 108, "wpm": 129.4, "speaking_wpm": 167.9, "pace_definition": "WPM uses total recording time. Speaking WPM uses the sum of recognized word durations, not a physiological articulation measure.", "pauses": [], "pause_definition": "Gaps of at least 1.5s between recognized words; long gaps are at least 3s. These may include noise or unrecognized speech.", "repeated_phrases": [], "repeated_words": {}, "average_sentence_length": 12.0, "longest_monologue": 50.07, "star": {"situation": {"words": 23, "seconds": 9.8, "percent": 21.9}, "task": {"words": 15, "seconds": 6.02, "percent": 13.5}, "actions": {"words": 70, "seconds": 28.82, "percent": 64.6}, "result": {"words": 0, "seconds": 0.0, "percent": 0.0}, "unknown": {"words": 0, "seconds": 0.0, "percent": 0.0}}, "numeric_mentions": 2, "ownership": {"individual": 5, "team": 0}, "activity": null, "redundancy_ratio": 0.0}, "analysis": {"scores": {"Delivery": 89.1, "Structure": 59.1, "Specificity": 100.0, "Impact": 0.0, "Overall": 62.0}, "score_explanation": "Overall averages the available category scores. Delivery weights pace around 145 WPM (70%) and long-gap control (30%). Structure combines meaningful STAR coverage (50%), a 15/10/50/25 time balance (35%), and section order (15%), scaled by coverage. Specificity rewards personal actions (25%), reasoning (25%), verification (20%), concrete detail (20%), and precise wording (10%), scaled by action depth and repetition. Relevance uses word-weighted semantic similarity, mapped from 0.05\u20130.75 to 0\u2013100; it is omitted when unavailable. Impact rewards an observable outcome (35%), a measure (25%), learning (20%), and a causal link (20%), scaled by result detail. Targets are adjustable coaching heuristics, not validated hiring standards.", "summary": "End with what changed, a truthful measure if available, or a concrete lesson.", "strengths": [{"kind": "observation", "text": "You included concrete numeric details. Preserve these when tightening the answer; a number is not by itself proof of impact.", "segments": [2, 3]}, {"kind": "observation", "text": "You described a decision or verification step. Keep the reasoning attached to your personal action.", "segments": [2]}], "improvements": [{"kind": "recommendation", "text": "End with what changed, a truthful measure if available, or a concrete lesson.", "segments": [3]}, {"kind": "recommendation", "text": "Rehearse the highlighted action in two sentences: what you chose, then why that choice mattered.", "segments": [2]}, {"kind": "recommendation", "text": "Tie the final sentence directly to the question; explain what this example demonstrates.", "segments": [3]}], "exercise": "Record another answer using four short beats: context, your responsibility, your decision and reason, then the observable outcome. End with what changed, a truthful measure if available, or a concrete lesson.", "outline": [{"section": "situation", "segments": [0], "prompt": "One sentence: what problem mattered?"}, {"section": "task", "segments": [1], "prompt": "One sentence: what did you own?"}, {"section": "actions", "segments": [2, 3], "prompt": "Two sentences: what did you decide, do, and verify?"}, {"section": "result", "segments": [], "prompt": "One sentence: what changed or what did you learn?"}], "intersections": [{"kind": "inference", "text": "Detected context takes 35% of transcript-segment time; actions take 65%. Review the section labels before using this balance.", "segments": [0, 1, 2, 3]}, {"kind": "inference", "text": "Detected actions pace is 146 WPM versus 129 WPM for the full recording. Segment pace excludes between-segment pauses.", "segments": [2, 3]}], "confidence": "limited", "limitations": ["Fictional demo dataset: transcript and timestamps are generated examples, not a recorded interview.", "Transcription can miss words or mishear numbers; check the transcript.", "STAR and relevance use an uncalibrated local similarity model, not a trained interview evaluator.", "Numeric mentions are evidence cues, not fact checking. Vague-word flags do not prove a claim is unsupported.", "No assessment of personality, honesty, emotion, confidence, accent, or employability.", "Sentence boundaries depend on transcription punctuation. Segment time is not the same as pure speech time."], "semantic_method": "rules-only (semantic model unavailable)", "intent_assessment": "Semantic overlap is a preliminary relevance signal; it cannot establish that the interviewer\u2019s intent was fully answered.", "ownership_clarity": "5 individual versus 0 team pronouns. Team language is appropriate; clarify your own decision when relevant.", "action_depth": "1 segments contain decision or verification cues. Inspect the linked transcript, not just the count.", "result_streng