insert into public.practice_attempts select * from jsonb_populate_record(null::public.practice_attempts,'{"id": "b7003859-ce14-57f4-a2f7-f245414996f7", "question_id": "team-2", "prompt": "Describe an experience working with someone whose communication or working style was difficult.", "competency": "teamwork", "linked_story_id": "4ca2cd70-0131-5199-a1ab-04a3be8f3d32", "created_at": "2026-09-25T16:00:00Z", "status": "completed", "duration": 44.73, "transcript": "During a research project, two students used different definitions for survey categories. Their results disagreed even though they used the same dataset. My task was to coordinate a reproducible analysis and protect the original responses. I scheduled a joint review, documented disputed definitions, and created a shared coding guide. I tested the guide on twenty responses with both students and compared disagreements before processing the full dataset. As a result, agreement rose from 72 percent to 94 percent and the team delivered a reproducible report. I learned to make assumptions explicit before dividing analysis work.", "metrics": {"duration": 44.73, "total_words": 95, "wpm": 127.4, "speaking_wpm": 167.7, "pace_definition": "WPM uses total recording time. Speaking WPM uses the sum of recognized word durations, not a physiological articulation measure.", "pauses": [], "pause_definition": "Gaps of at least 1.5s between recognized words; long gaps are at least 3s. These may include noise or unrecognized speech.", "repeated_phrases": [], "repeated_words": {}, "average_sentence_length": 13.6, "longest_monologue": 44.73, "star": {"situation": {"words": 22, "seconds": 9.37, "percent": 23.8}, "task": {"words": 0, "seconds": 0.0, "percent": 0.0}, "actions": {"words": 73, "seconds": 29.93, "percent": 76.2}, "result": {"words": 0, "seconds": 0.0, "percent": 0.0}, "unknown": {"words": 0, "seconds": 0.0, "percent": 0.0}}, "numeric_mentions": 3, "ownership": {"individual": 4, "team": 0}, "activity": null, "redundancy_