insert into public.practice_segments values ('c1915fcd-b343-59c3-834f-39dbd7d0ce43',3,'{"index": 3, "start": 32.705, "end": 47.309, "text": "As a result, median search latency fell from 1400 to 190 milliseconds in the test workload. The improvement enabled the trial to continue. I learned to measure each layer before choosing a fix.", "words": [{"text": "As", "start": 32.705, "end": 33.087, "confidence": 0.95}, {"text": "a", "start": 33.149, "end": 33.532, "confidence": 0.95}, {"text": "result,", "start": 33.594, "end": 33.976, "confidence": 0.95}, {"text": "median", "start": 34.038, "end": 34.421, "confidence": 0.95}, {"text": "search", "start": 34.483, "end": 34.865, "confidence": 0.95}, {"text": "latency", "start": 34.927, "end": 35.309, "confidence": 0.95}, {"text": "fell", "start": 35.372, "end": 35.754, "confidence": 0.95}, {"text": "from", "start": 35.816, "end": 36.198, "confidence": 0.95}, {"text": "1400", "start": 36.261, "end": 36.643, "confidence": 0.95}, {"text": "to", "start": 36.705, "end": 37.087, "confidence": 0.95}, {"text": "190", "start": 37.149, "end": 37.532, "confidence": 0.95}, {"text": "milliseconds", "start": 37.594, "end": 37.976, "confidence": 0.95}, {"text": "in", "start": 38.038, "end": 38.421, "confidence": 0.95}, {"text": "the", "start": 38.483, "end": 38.865, "confidence": 0.95}, {"text": "test", "start": 38.927, "end": 39.309, "confidence": 0.95}, {"text": "workload.", "start": 39.372, "end": 39.754, "confidence": 0.95}, {"text": "The", "start": 39.816, "end": 40.198, "confidence": 0.95}, {"text": "improvement", "start": 40.261, "end": 40.643, "confidence": 0.95}, {"text": "enabled", "start": 40.705, "end": 41.087, "confidence": 0.95}, {"text": "the", "start": 41.149, "end": 41.532, "confidence": 0.95}, {"text": "trial", "start": 41.594, "end": 41.976, "confidence": 0.95}, {"text": "to", "start": 42.038, "end": 42.421, "confidence": 0.95}, {"text": "continue.", "start": 42.483, "end": 42.865, "confidence": 0.95}, {"text": "I", "star