insert into public.practice_attempts select * from jsonb_populate_record(null::public.practice_attempts,'{"id": "2c26476a-0833-5a94-b5d8-22bda5b159e0", "question_id": "prob-2", "prompt": "Tell me about a time you had to simplify an overly complicated system or process.", "competency": "problem_solving", "linked_story_id": "224c867e-988c-57b0-a156-f86c05ab0a0e", "created_at": "2026-09-26T14:00:00Z", "status": "completed", "duration": 45.81, "transcript": "During a campus mapping project, the shortest route sometimes included stairs that wheelchair users could not use. My task was to build a route filter that respected accessibility constraints and explained missing route data. I modeled step-free edges, wrote graph tests, and compared route outputs with manual checks. I interviewed two accessibility volunteers and tested detours. I chose explicit unknown labels instead of assuming every unmarked entrance was accessible. As a result, all twelve reviewed routes avoided known stairs and displayed uncertain entrances. The design prevented misleading directions. I learned that missing data must be visible to users.", "metrics": {"duration": 45.81, "total_words": 98, "wpm": 128.3, "speaking_wpm": 168.3, "pace_definition": "WPM uses total recording time. Speaking WPM uses the sum of recognized word durations, not a physiological articulation measure.", "pauses": [], "pause_definition": "Gaps of at least 1.5s between recognized words; long gaps are at least 3s. These may include noise or unrecognized speech.", "repeated_phrases": [], "repeated_words": {}, "average_sentence_length": 12.2, "longest_monologue": 45.81, "star": {"situation": {"words": 17, "seconds": 7.23, "percent": 17.9}, "task": {"words": 0, "seconds": 0.0, "percent": 0.0}, "actions": {"words": 81, "seconds": 33.16, "percent": 82.1}, "result": {"words": 0, "seconds": 0.0, "percent": 0.0}, "unknown": {"words": 0, "seconds": 0.0, "percent": 0.0}}, "numeric_mentions": 1, "ownership": {"individual": 5, "team": 0}, 